import type { ProjectDirectoryHandle } from './projectDirectoryService';
import type { ProjectState, ProjectType } from '../../types';

export const PROJECT_MANIFEST_FILE = 'manifest.json';
export const DATASET_MANIFEST_FILE = 'dataset.json';
export const PROJECT_DATASET_DIRECTORY = 'dataset';
/** Raw materials of a v3 project; edits and crops generated by tools live in `inbox/edits`. */
export const PROJECT_INBOX_DIRECTORY = 'inbox';
export const PROJECT_EDITS_DIRECTORY = 'inbox/edits';
/** Pre-v3 locations; only the layout migration and the v2 reader refer to them. */
export const LEGACY_SOURCE_DIRECTORY = 'src';
export const LEGACY_SHARED_DIRECTORY = 'src/shared';
export const LEGACY_ASSETS_DIRECTORY = 'src/assets';
/** Pre-v3 preview cache folder; moved into the service folder by the layout migration. */
export const LEGACY_CACHE_DIRECTORY = '.cache';
export const PROJECT_GIT_DIRECTORY = '.git';

export const PROJECT_DATA_DIRECTORY = '.dataset-creator-data';

/** Service folder of a v3 project: settings, cache, versions, migration journals and backups. */
export const PROJECT_INTERNAL_DIRECTORY = '.datasetcreator';
export const PROJECT_FILE = `${PROJECT_INTERNAL_DIRECTORY}/project.json`;
export const PROJECT_PROJECT_FORMAT = 'dataset-creator-project';
/** Per-file registry of a v3 project: stable ids, size/mtime fingerprint and optional SHA-256. */
export const PROJECT_ASSETS_FILE = `${PROJECT_INTERNAL_DIRECTORY}/assets.json`;
export const PROJECT_ASSETS_FORMAT = 'dataset-creator-assets';
/** Output folder of exports; never scanned for project assets. */
export const PROJECT_EXPORTS_DIRECTORY = 'exports';

export const PROJECT_LAYOUT = {
  rawDir: PROJECT_INBOX_DIRECTORY,
  generatedDir: PROJECT_EDITS_DIRECTORY,
  datasetDir: PROJECT_DATASET_DIRECTORY,
  internalDir: PROJECT_INTERNAL_DIRECTORY,
  projectFile: PROJECT_FILE,
  assetsFile: PROJECT_ASSETS_FILE,
  cacheDir: `${PROJECT_INTERNAL_DIRECTORY}/cache`,
  versionsDir: `${PROJECT_INTERNAL_DIRECTORY}/versions`,
  journalDir: `${PROJECT_INTERNAL_DIRECTORY}/journal`,
  backupDir: `${PROJECT_INTERNAL_DIRECTORY}/backup`,
  // Pre-v3 service names stay hidden until the layout migration moves them.
  internalRootNames: [PROJECT_INTERNAL_DIRECTORY, LEGACY_CACHE_DIRECTORY, PROJECT_DATA_DIRECTORY, PROJECT_GIT_DIRECTORY],
} as const;

/** Folders inside the service folder that are never snapshotted and never removed by a version restore. */
export const PROJECT_INTERNAL_PRESERVED_DIRECTORIES = ['cache', 'journal', 'versions', 'backup'] as const;

const INTERNAL_ENTRY_NAMES = new Set<string>(PROJECT_LAYOUT.internalRootNames);

/** True for service entries (cache, recovery data, versions) that are not user project content; applied at any depth. */
export const isInternalProjectEntry = (name: string, _depth = 0): boolean => INTERNAL_ENTRY_NAMES.has(name);

export const REQUIRED_PROJECT_DIRECTORIES = [
  PROJECT_INTERNAL_DIRECTORY,
  PROJECT_LAYOUT.cacheDir,
  PROJECT_DATASET_DIRECTORY,
  PROJECT_INBOX_DIRECTORY,
  PROJECT_EDITS_DIRECTORY,
] as const;

export type DatasetTrainingSettings = {
  epochs?: number;
  repeats?: number;
  alpha?: number;
  dim?: number;
};

export type DatasetManifest = {
  format: 'dataset-creator-dataset';
  version: 2 | 3;
  name: string;
  projectType: ProjectType;
  description: string;
  triggerWord: string;
  imageCount: number;
  classCount: number;
  classRepeats: Record<string, number>;
  training?: DatasetTrainingSettings;
  updatedAt: string;
  assetIds?: string[];
  assetPaths?: string[];
  psdAssetPaths?: string[];
  assetOrder?: string[];
  overwriteCaptions?: boolean;
  captionOverrides?: Record<string, string[]>;
  createdAt?: string;
};

const pathParts = (path: string): string[] => path.split('/').filter(Boolean);

const writeTextFile = async (directory: ProjectDirectoryHandle, name: string, value: string) => {
  const handle = await directory.getFileHandle(name, { create: true });
  const writable = await handle.createWritable();
  await writable.write(value);
  await writable.close();
};

export const getDirectoryAtPath = async (
  root: ProjectDirectoryHandle,
  path: string,
  create = false
): Promise<ProjectDirectoryHandle> => {
  let directory = root;
  for (const part of pathParts(path)) {
    directory = await directory.getDirectoryHandle(part, { create });
  }
  return directory;
};

export const readDatasetManifest = async (root: ProjectDirectoryHandle): Promise<DatasetManifest | null> => {
  try {
    const file = await (await root.getFileHandle(DATASET_MANIFEST_FILE)).getFile();
    const manifest = JSON.parse(await file.text()) as DatasetManifest;
    return manifest.format === 'dataset-creator-dataset' && (manifest.version === 2 || manifest.version === 3) ? manifest : null;
  } catch {
    return null;
  }
};

export const writeDatasetManifest = async (
  root: ProjectDirectoryHandle,
  manifest: DatasetManifest
): Promise<void> => writeTextFile(root, DATASET_MANIFEST_FILE, JSON.stringify(manifest, null, 2));

export const isGitFile = async (root: ProjectDirectoryHandle): Promise<boolean> => {
  try {
    await root.getFileHandle(PROJECT_GIT_DIRECTORY);
    return true;
  } catch {
    return false;
  }
};

export const ensureProjectLayout = async (
  root: ProjectDirectoryHandle,
  _project?: Pick<ProjectState, 'name' | 'projectType' | 'taggingConfig' | 'dataset'>
): Promise<DatasetManifest | null> => {
  // A real .git folder or gitfile is never created, changed or required.
  await Promise.all(REQUIRED_PROJECT_DIRECTORIES.map((path) => getDirectoryAtPath(root, path, true)));
  return readDatasetManifest(root);
};

export type ProjectLayoutVersion = 'v3' | 'v2' | 'none';

const hasFile = async (root: ProjectDirectoryHandle, path: string): Promise<boolean> => {
  try {
    const parts = pathParts(path);
    const directory = await getDirectoryAtPath(root, parts.slice(0, -1).join('/'));
    await directory.getFileHandle(parts[parts.length - 1]);
    return true;
  } catch (error) {
    if ((error as { name?: string })?.name === 'NotFoundError' || (error as { name?: string })?.name === 'TypeMismatchError') return false;
    throw error;
  }
};

/** v3: `.datasetcreator/project.json`; v2: legacy `manifest.json` (v1 and v2 formats); none: not a project. */
export const detectProjectLayout = async (root: ProjectDirectoryHandle): Promise<ProjectLayoutVersion> => {
  if (await hasFile(root, PROJECT_FILE)) return 'v3';
  if (await hasFile(root, PROJECT_MANIFEST_FILE)) return 'v2';
  return 'none';
};

export const isProjectWorkspacePath = (path: string, workspace: 'dataset' | 'shared' | 'assets' | 'legacy-shared'): boolean => {
  const normalizedPath = path.replace(/^Project\//, '');
  const root = workspace === 'dataset'
    ? PROJECT_DATASET_DIRECTORY
    : workspace === 'shared'
      ? PROJECT_INBOX_DIRECTORY
      : workspace === 'legacy-shared'
        ? LEGACY_SHARED_DIRECTORY
        : PROJECT_EDITS_DIRECTORY;
  return normalizedPath === root || normalizedPath.startsWith(`${root}/`);
};
